PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `users` (`userId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `firstName` TEXT NOT NULL, `lastName` TEXT, `emailId` TEXT, `phoneNumber` TEXT, `status` TEXT NOT NULL, `passwordHash` TEXT, `createdDate` TEXT NOT NULL, `isPinSet` INTEGER NOT NULL, `hashPIN` TEXT, `firebaseUserId` TEXT, `userCode` TEXT NOT NULL);
COMMIT;